106	);
107	COMMENT ON TABLE term_rule IS '术语规则：属于某术语版本的不可变规则，按 sourceTerm 与目标语言唯一，每版本 0~100 条';
108	COMMENT ON COLUMN term_rule.document_id IS '所属文档 ID';
109	COMMENT ON COLUMN term_rule.term_version IS '所属术语版本号';
110	COMMENT ON COLUMN term_rule.source_term IS '源文术语，Unicode 原文、区分大小写，按连续子串匹配';
111	COMMENT ON COLUMN term_rule.language IS '目标语言码，小写';
112	COMMENT ON COLUMN term_rule.required_translation IS '该术语在目标语言中的必译文本，非空';
113	
114	CREATE TABLE IF NOT EXISTS request_log (
