121	COMMENT ON TABLE request_log IS '写操作幂等去重：全局唯一 requestId，仅记录成功结果，与业务变更原子提交';
122	COMMENT ON COLUMN request_log.request_id IS '全局唯一请求 ID';
123	COMMENT ON COLUMN request_log.request_hash IS '请求参数规范化后的 SHA-256 摘要；同键异参返回 409';
124	COMMENT ON COLUMN request_log.response_status IS '原成功响应的 HTTP 状态码，用于重放';
125	COMMENT ON COLUMN request_log.response_body IS '原成功响应体 JSON，用于重放';
