1	package com.example.starter.translation;
2	
3	import com.fasterxml.jackson.databind.JsonNode;
4	import com.fasterxml.jackson.databind.ObjectMapper;
5	import org.junit.jupiter.api.BeforeEach;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
8	import org.springframework.boot.test.context.SpringBootTest;
9	import org.springframework.jdbc.core.JdbcTemplate;
10	import org.springframework.test.context.ActiveProfiles;
11	import org.springframework.test.web.servlet.MockMvc;
12	import org.springframework.test.web.servlet.MvcResult;
13	import org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;
14	import org.springframework.test.web.servlet.request.MockMvcRequestBuilders;
15	
16	import java.util.UUID;
17	
18	/**
19	 * 集成测试基类：独立 H2 内存库（translation_test），每个用例前清空全部业务表，
20	 * 避免用例间顺序依赖；测试上下文关闭时连接池关闭，内存库随之释放。
21	 */
22	@SpringBootTest
23	@AutoConfigureMockMvc
24	@ActiveProfiles("test")
25	public abstract class AbstractIntegrationTest {
26	
27	    @Autowired
28	    protected MockMvc mockMvc;
29	
30	    @Autowired
31	    protected JdbcTemplate jdbc;
32	
33	    @Autowired
34	    protected ObjectMapper objectMapper;
35	
36	    @BeforeEach
37	    void cleanTables() {
38	        jdbc.update("DELETE FROM approval");
39	        jdbc.update("DELETE FROM translation");
40	        jdbc.update("DELETE FROM segment");
41	        jdbc.update("DELETE FROM release_snapshot");
42	        jdbc.update("DELETE FROM term_rule");
43	        jdbc.update("DELETE FROM term_version");
44	        jdbc.update("DELETE FROM request_log");
45	        jdbc.update("DELETE FROM document");
46	    }
47	
48	    protected String newRequestId() {
49	        return UUID.randomUUID().toString();
50	    }
51	
52	    /** POST JSON，返回响应状态与解析后的响应体。 */
53	    protected ApiResult postJson(String url, String body) throws Exception {
54	        return perform(MockMvcRequestBuilders.post(url), body, null);
55	    }
56	
57	    protected ApiResult postJson(String url, String body, String actorId) throws Exception {
58	        return perform(MockMvcRequestBuilders.post(url), body, actorId);
59	    }
60	
61	    protected ApiResult putJson(String url, String body) throws Exception {
62	        return perform(MockMvcRequestBuilders.put(url), body, null);
63	    }
64	
65	    protected ApiResult putJson(String url, String body, String actorId) throws Exception {
66	        return perform(MockMvcRequestBuilders.put(url), body, actorId);
67	    }
68	
69	    protected ApiResult getJson(String url) throws Exception {
70	        MvcResult result = mockMvc.perform(MockMvcRequestBuilders.get(url)).andReturn();
71	        return toApiResult(result);
72	    }
73	
74	    private ApiResult perform(MockHttpServletRequestBuilder builder, String body, String actorId)
75	            throws Exception {
76	        builder.contentType("application/json").content(body);
77	        if (actorId != null) {
78	            builder.header("X-Actor-Id", actorId);
79	        }
80	        MvcResult result = mockMvc.perform(builder).andReturn();
81	        return toApiResult(result);
82	    }
83	
84	    private ApiResult toApiResult(MvcResult result) throws Exception {
85	        int status = result.getResponse().getStatus();
86	        String content = result.getResponse().getContentAsString();
87	        JsonNode json = content.isBlank() ? null : objectMapper.readTree(content);
88	        return new ApiResult(status, json);
89	    }
90	
91	    /** 建文档并返回 documentId。 */
92	    protected long createDocument(String requestId, String targetLanguagesJson, String segmentsJson)
93	            throws Exception {
94	        String body = "{\"requestId\":\"" + requestId + "\",\"targetLanguages\":" + targetLanguagesJson
95	                + ",\"segments\":" + segmentsJson + "}";
96	        ApiResult result = postJson("/api/documents", body);
97	        if (result.status() != 201) {
98	            throw new IllegalStateException("建文档失败: " + result.status() + " " + result.body());
99	        }
100	        return result.body().get("documentId").asLong();
101	    }
102	
103	    protected ApiResult submitTranslation(long documentId, String segmentId, String language, String actorId,
104	                                          String content, int sourceVersion, String requestId) throws Exception {
105	        String body = "{\"requestId\":\"" + requestId + "\",\"content\":\"" + content
106	                + "\",\"sourceVersion\":" + sourceVersion + "}";
107	        return putJson("/api/documents/" + documentId + "/segments/" + segmentId + "/translations/" + language,
108	                body, actorId);
109	    }
110	
111	    protected ApiResult approve(long documentId, String segmentId, String language, String actorId,
112	                                int translationVersion, String requestId) throws Exception {
113	        String body = "{\"requestId\":\"" + requestId + "\",\"translationVersion\":" + translationVersion + "}";
114	        return postJson("/api/documents/" + documentId + "/segments/" + segmentId + "/translations/" + language
115	                + "/approve", body, actorId);
116	    }
117	
118	    protected ApiResult publish(long documentId, int expectedDraftVersion, int expectedPublishedVersion,
119	                                String requestId) throws Exception {
120	        String body = "{\"requestId\":\"" + requestId + "\",\"expectedDraftVersion\":" + expectedDraftVersion
121	                + ",\"expectedPublishedVersion\":" + expectedPublishedVersion + "}";
122	        return postJson("/api/documents/" + documentId + "/publish", body);
123	    }
124	
125	    /** 新增术语版本：rulesJson 为规则数组 JSON。 */
126	    protected ApiResult updateTerms(long documentId, int expectedTermVersion, String rulesJson,
127	                                    String requestId) throws Exception {
128	        String body = "{\"requestId\":\"" + requestId + "\",\"expectedTermVersion\":" + expectedTermVersion
129	                + ",\"rules\":" + rulesJson + "}";
130	        return putJson("/api/documents/" + documentId + "/terms", body);
131	    }
132	
133	    /** HTTP 响应结果：状态码与 JSON 响应体。 */
134	    protected record ApiResult(int status, JsonNode body) {
135	    }
136	}
